def top_k(probs, k):
    return normalize(dict(list(probs.items())[:k]))

def top_p(probs, p):
    keep, total = {}, 0
    for t, x in probs.items():
        keep[t] = x
        total += x
        if total &gt;= p:
            break
    return normalize(keep)

def min_p(probs, m):
    top = max(probs.values())
    return normalize({t: x for t, x in probs.items() if x &gt;= m * top})



